export default async function HelpPage({ params }: PageProps<"/help/[[...topic]]">) {
  const { topic } = await params;
  return <h1>Help: {topic ? topic.join(" / ") : "all topics"}</h1>;
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

export function NavLink({ href, children }: { href: string; children: React.ReactNode }) {
  const pathname = usePathname();
  const active = pathname === href || pathname.startsWith(`${href}/`);
  return (
    <Link href={href} aria-current={active ? "page" : undefined}>
      {children}
    </Link>
  );
}

import Link from "next/link";
import { Suspense } from "react";
import { NavLink } from "@/components/nav-link";

const links = [
  { href: "/products", label: "Products" },
  { href: "/about", label: "About" },
];

export function SiteHeader() {
  return (
    <header className="flex gap-6 border-b p-4">
      <Link href="/" className="font-semibold">Trailhead</Link>
      <nav className="flex gap-4">
        {links.map(({ href, label }) => (
          <Suspense key={href} fallback={<Link href={href}>{label}</Link>}>
            <NavLink href={href}>{label}</NavLink>
          </Suspense>
        ))}
      </nav>
    </header>
  );
}

"use client";

export default function ProductsError({ error, retry }: { error: unknown; retry: () => void }) {
  const digest = error instanceof Error && "digest" in error ? String(error.digest) : undefined;
  return (
    <section role="alert">
      <h2 className="font-semibold">We couldn't load the products</h2>
      <p>Try again in a moment.{digest && ` Error ${digest}.`}</p>
      <button onClick={() => retry()}>Try again</button>
    </section>
  );
}

