import { Suspense } from "react";
import { Modal } from "@/components/modal";
import { formatPrice } from "@/lib/format";
import { getProduct } from "@/lib/products";

export default function QuickView({ params }: PageProps<"/products/[slug]">) {
  return (
    <Modal>
      <Suspense fallback={<p>Loading…</p>}>
        <QuickViewBody params={params} />
      </Suspense>
    </Modal>
  );
}

async function QuickViewBody({ params }: Pick<PageProps<"/products/[slug]">, "params">) {
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) return <p>We don't sell that.</p>;
  return (
    <p>
      {product.name}, {formatPrice(product.priceCents)}
    </p>
  );
}
